import './shell.js';
import {getState,saveState,updateState,makeId,projectById,addActivity,resetState,statuses} from './store.js';
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)], page=document.body.dataset.page||'overview';
const content=$('#appContent');
const fmtDate=(s)=>{if(!s)return '—';const d=new Date(`${s}T00:00:00`);return new Intl.DateTimeFormat('ar-SA',{day:'numeric',month:'short'}).format(d)};
const esc=(s)=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const projectName=(id,s=getState())=>s.projects.find(p=>p.id===id)?.name||'مشروع غير محدد';
const icon=(name)=>{const i={plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 10h18"/>',alert:'<path d="m10.3 3.9-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.7-3.1l-8-14a2 2 0 0 0-3.4 0Z"/><path d="M12 9v4m0 4h.01"/>',spark:'<path d="m12 3 2 6 6 2-6 2-2 6-2-6-6-2 6-2z"/>',check:'<path d="m5 12 4 4L19 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',file:'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><path d="M14 2v6h6"/>',download:'<path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4m4-5 5 5 5-5m-5 5V3"/>',search:'<circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/>',building:'<path d="M3 21h18M5 21V6l7-3 7 3v15M9 9h.01M15 9h.01M9 13h.01M15 13h.01M10 21v-4h4v4"/>',git:'<circle cx="6" cy="5" r="2"/><circle cx="18" cy="7" r="2"/><circle cx="8" cy="19" r="2"/><path d="M6 7v4a4 4 0 0 0 4 4h4a4 4 0 0 0 4-4V9M8 17v-2"/>',chart:'<path d="M3 3v18h18M7 14l4-4 4 3 6-7"/>',users:'<path d="M16 21v-2a4 4 0 0 0-4-4H7a4 4 0 0 0-4 4v2M9.5 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8ZM20 8v6m3-3h-6"/>'};return `<svg viewBox="0 0 24 24" aria-hidden="true">${i[name]||''}</svg>`};
function toast(message){const region=document.querySelector('.toast-region')||(()=>{const n=document.createElement('div');n.className='toast-region';n.setAttribute('aria-live','polite');document.body.append(n);return n})();const t=document.createElement('div');t.className='toast';t.innerHTML=`<b>✓</b>${esc(message)}`;region.append(t);setTimeout(()=>t.remove(),3200)}
function renderHeading(kicker,title,desc,actions=''){return `<div class="page-heading"><div><div class="page-kicker">${kicker}</div><h1>${title}</h1><p>${desc}</p></div><div class="heading-actions">${actions}</div></div>`}
function button(action,text,kind='btn',ic=''){return `<button class="${kind}" data-action="${action}">${ic?icon(ic):''}${text}</button>`}
function statusClass(v){if(/متأخر|تعارض|عاجل|رفض/.test(v))return 'bad';if(/انتظار|متابعة|تنسيق|مراجعة|عالي/.test(v))return 'warn';if(/معتمد|مكتمل|المسار/.test(v))return 'good';return 'info'}
function status(text){return `<span class="status ${statusClass(text)}">${esc(text)}</span>`}
function projectTable(rows){return `<div class="table-wrap"><table class="data-table"><thead><tr><th>المشروع</th><th>العميل</th><th>مدير المشروع</th><th>موعد التسليم</th><th>الإنجاز</th><th>الحالة</th><th></th></tr></thead><tbody>${rows.map(p=>`<tr><td><div class="row-main"><span class="project-mark">${esc(p.code.slice(-3))}</span><span><strong>${esc(p.name)}</strong><small>${esc(p.code)} · ${esc(p.location)}</small></span></div></td><td>${esc(p.client)}</td><td>${esc(p.manager)}</td><td>${fmtDate(p.due)}</td><td><div style="display:flex;align-items:center;gap:8px"><span class="progress"><span style="width:${p.progress}%"></span></span><small>${p.progress}%</small></div></td><td>${status(p.status)}</td><td><a class="btn btn-sm btn-icon" href="workspace.html?project=${encodeURIComponent(p.id)}" aria-label="فتح المشروع">${icon('arrow')}</a></td></tr>`).join('')}</tbody></table></div>`}
function activityList(items){return `<div class="activity">${items.slice(0,4).map(a=>`<div class="activity-row"><i class="activity-mark"></i><div><strong>${esc(a.text)}</strong><p>${esc(a.detail)}</p><time>${esc(a.time)}</time></div></div>`).join('')}</div>`}
function overview(){const s=getState(),open=s.tasks.filter(t=>t.status!=='مكتملة').length,late=s.tasks.filter(t=>t.status==='متأخرة').length,pending=s.approvals.filter(a=>a.status==='بانتظار العميل').length,changes=s.changes.filter(c=>!['مكتمل','مغلق'].includes(c.status)).length;content.innerHTML=`${renderHeading('الخميس، ١ أكتوبر ٢٠٢٦ · مساحة المكتب','مرحبًا جوري','ملخص المكتب اليوم، والمشاريع والأعمال التي تحتاج إلى متابعة.',button('new-project','مشروع جديد','btn btn-primary','plus'))}<div class="stats-grid grid"><article class="panel stat-card"><div class="stat-label">المشاريع النشطة<span class="stat-icon">${icon('building')}</span></div><div class="stat-value">${String(s.projects.length).padStart(2,'0')}</div><div class="stat-foot">عبر ${new Set(s.projects.map(p=>p.location)).size} مدن</div></article><article class="panel stat-card"><div class="stat-label">المهام المفتوحة<span class="stat-icon">${icon('check')}</span></div><div class="stat-value">${String(open).padStart(2,'0')}</div><div class="stat-foot"><b class="${late?'negative':'positive'}">${late} متأخرة</b> · ${open-late} قيد العمل</div></article><article class="panel stat-card"><div class="stat-label">اعتمادات العميل<span class="stat-icon gold">${icon('clock')}</span></div><div class="stat-value">${String(pending).padStart(2,'0')}</div><div class="stat-foot">بانتظار الرد أو المراجعة</div></article><article class="panel stat-card"><div class="stat-label">تغييرات مفتوحة<span class="stat-icon red">${icon('git')}</span></div><div class="stat-value">${String(changes).padStart(2,'0')}</div><div class="stat-foot">تحتاج تنسيقًا بين التخصصات</div></article></div><div class="grid grid-two"><section class="panel panel-pad"><div class="panel-head"><div><h2>مشاريع المكتب</h2><p>حالة الإنجاز والتسليم والمسؤولية</p></div><a class="link" href="projects.html">كل المشاريع ←</a></div>${projectTable(s.projects)}</section><section class="panel office-brief"><div class="brief-title"><span class="brief-icon">${icon('spark')}</span><span><strong>ملخص المتابعة</strong><small>مصادره: المهام والاعتمادات والإصدارات</small></span><span class="demo-label" style="margin-right:auto">بيانات نموذجية</span></div><p class="brief-text">${late?`لديك ${late} مهام متأخرة و${pending} اعتمادات تنتظر الرد.`:'لا توجد مهام متأخرة حاليًا.'} راجعي تعارض الإصدارات قبل إصدار حزمة التسليم.</p><div class="brief-list"><div class="brief-item">${s.tasks.filter(t=>t.status==='متأخرة').slice(0,1).map(t=>`مهمة متأخرة: ${esc(t.title)} · ${esc(projectName(t.project,s))}`).join('')||'لا توجد مهام متأخرة في البيانات الحالية.'}</div><div class="brief-item">${pending} طلب اعتماد بانتظار العميل.</div><div class="brief-item">M-203 v2 يشير إلى إصدار أقدم من المخطط A-104 v3.</div></div><div class="brief-footer"><span>استنادًا إلى بيانات العرض التجريبية</span><a class="link" href="ai.html">افتح مركز الذكاء ←</a></div></section></div><div class="grid grid-halves"><section class="panel panel-pad"><div class="panel-head"><div><h2>يتطلب متابعة</h2><p>مرتبة حسب تأثيرها على التسليم</p></div><a class="link" href="changes.html">عرض التغييرات</a></div><div class="attention-list"><div class="attention-row"><span class="attention-symbol red">${icon('alert')}</span><div><strong>تعارض مرجع الإصدار</strong><small>M-203 v2 ما زال مرتبطًا بـ A-104 v2</small></div>${status('مراجعة مطلوبة')}</div><div class="attention-row"><span class="attention-symbol gold">${icon('clock')}</span><div><strong>${pending} اعتمادات تنتظر العميل</strong><small>مخطط A-104 v3 · تقرير التقدم</small></div>${status('بانتظار العميل')}</div><div class="attention-row"><span class="attention-symbol">${icon('calendar')}</span><div><strong>حزمة التصميم الأولي</strong><small>مجمع النخيل · التسليم ٧ أكتوبر</small></div><span class="tag gold">بعد ٦ أيام</span></div></div></section><section class="panel panel-pad"><div class="panel-head"><div><h2>آخر نشاط</h2><p>تحديثات فريق المشروع</p></div><a class="link" href="reports.html">سجل المكتب</a></div>${activityList(s.activity)}</section></div>`}
function projects(){const s=getState();content.innerHTML=`${renderHeading('مساحة العمل / المشاريع','المشاريع','كل مشروع ومسؤولياته ومواعيده في قائمة واحدة.',button('new-project','إضافة مشروع','btn btn-primary','plus'))}<div class="filter-bar"><input class="search-input" id="projectFilter" placeholder="ابحث باسم المشروع أو الرمز"><select class="select" id="projectStatus"><option value="">كل الحالات</option><option>على المسار</option><option>يحتاج متابعة</option><option>متأخر</option></select><span class="count-note">${s.projects.length} مشاريع</span></div><section class="panel">${projectTable(s.projects)}</section><div class="grid grid-halves" style="margin-top:14px"><section class="panel panel-pad"><div class="panel-head"><div><h2>التسليمات القادمة</h2><p>المعالم القريبة للمكتب</p></div></div><div class="attention-list">${s.projects.slice().sort((a,b)=>a.due.localeCompare(b.due)).slice(0,3).map(p=>`<div class="attention-row"><span class="attention-symbol">${icon('calendar')}</span><div><strong>${esc(p.name)}</strong><small>التسليم المستهدف · ${fmtDate(p.due)}</small></div><span class="tag">${p.progress}%</span></div>`).join('')}</div></section><section class="panel panel-pad"><div class="panel-head"><div><h2>ملخص المحفظة</h2><p>أرقام محسوبة من سجل المشاريع</p></div></div><div class="detail-row"><span>إجمالي قيمة المشاريع</span><b>${(s.projects.reduce((n,p)=>n+(Number(p.budget)||0),0)/1000000).toFixed(2)} مليون ر.س</b></div><div class="detail-row"><span>متوسط الإنجاز</span><b>${Math.round(s.projects.reduce((n,p)=>n+p.progress,0)/s.projects.length)}٪</b></div><div class="detail-row"><span>على المسار</span><b>${s.projects.filter(p=>p.status==='على المسار').length} من ${s.projects.length}</b></div></section></div>`}
function workspace(){const s=getState(),id=new URLSearchParams(location.search).get('project')||s.settings.project,p=projectById(id,s);content.innerHTML=`${renderHeading(`${esc(p.code)} / مساحة المشروع`,esc(p.name),`${esc(p.type)} · ${esc(p.location)} · العميل ${esc(p.client)}`,button('new-change','طلب تغيير','btn btn-primary','plus'))}<div class="page-tabs"><a class="page-tab active" href="workspace.html?project=${p.id}">نظرة عامة</a><a class="page-tab" href="files.html?project=${p.id}">الملفات</a><a class="page-tab" href="changes.html?project=${p.id}">التغييرات</a><a class="page-tab" href="thread.html?project=${p.id}">ترابط العناصر</a><a class="page-tab" href="tasks.html?project=${p.id}">المهام</a><a class="page-tab" href="approvals.html?project=${p.id}">الاعتمادات</a><a class="page-tab" href="reports.html?project=${p.id}">التقارير</a></div><div class="stats-grid grid"><article class="panel stat-card"><div class="stat-label">إنجاز المشروع<span class="stat-icon">${icon('chart')}</span></div><div class="stat-value">${p.progress}%</div><div class="progress"><span style="width:${p.progress}%"></span></div></article><article class="panel stat-card"><div class="stat-label">مهام مفتوحة<span class="stat-icon">${icon('check')}</span></div><div class="stat-value">${s.tasks.filter(t=>t.project===p.id&&t.status!=='مكتملة').length}</div><div class="stat-foot">${s.tasks.filter(t=>t.project===p.id&&t.status==='متأخرة').length} متأخرة</div></article><article class="panel stat-card"><div class="stat-label">تغييرات مفتوحة<span class="stat-icon gold">${icon('git')}</span></div><div class="stat-value">${s.changes.filter(c=>c.project===p.id&&c.status!=='مكتمل').length}</div><div class="stat-foot">منها CR-017 قيد التنسيق</div></article><article class="panel stat-card"><div class="stat-label">التسليم المستهدف<span class="stat-icon blue">${icon('calendar')}</span></div><div class="stat-value" style="font-size:18px">${fmtDate(p.due)}</div><div class="stat-foot">مدير المشروع: ${esc(p.manager)}</div></article></div><div class="grid grid-two"><section class="panel panel-pad"><div class="panel-head"><div><h2>سير التغيير CR-017</h2><p>من طلب العميل إلى تحديث الملفات والاعتماد</p></div><a class="link" href="changes.html">تفاصيل التغيير</a></div><div class="flow-steps"><div class="flow-step done"><small>١ · اكتمل</small><strong>طلب العميل</strong></div><span class="flow-arrow">←</span><div class="flow-step done"><small>٢ · اكتمل</small><strong>تحليل الأثر</strong></div><span class="flow-arrow">←</span><div class="flow-step active"><small>٣ · جارٍ</small><strong>تنسيق التخصصات</strong></div><span class="flow-arrow">←</span><div class="flow-step"><small>٤ · تالٍ</small><strong>اعتماد العميل</strong></div></div><div class="notice"><span>${icon('alert')}</span><div><strong>تعارض إصدار واحد يحتاج مراجعة.</strong> ملف M-203 v2 يستخدم مرجعًا أقدم من A-104 v3.</div></div></section><section class="panel panel-pad"><div class="panel-head"><div><h2>فريق المشروع</h2><p>${p.team} أعضاء · ${esc(p.manager)} مدير المشروع</p></div><a class="link" href="team.html">إدارة الفريق</a></div>${getState().team.slice(0,3).map(t=>`<div class="attention-row"><span class="avatar ${esc(t.color)}">${esc(t.initial)}</span><div><strong>${esc(t.name)}</strong><small>${esc(t.discipline)}</small></div><span class="tag">${t.capacity}%</span></div>`).join('')}</section></div><div class="grid grid-halves" style="margin-top:14px"><section class="panel panel-pad"><div class="panel-head"><div><h2>المهام التالية</h2><p>أقرب المهام إلى موعد التسليم</p></div><a class="link" href="tasks.html">كل المهام</a></div>${taskList(getState().tasks.filter(t=>t.project===p.id).slice(0,4))}</section><section class="panel panel-pad"><div class="panel-head"><div><h2>آخر الملفات</h2><p>سجل الإصدارات والمراجعات</p></div><a class="link" href="files.html">كل الملفات</a></div>${fileList(getState().files.slice(0,3))}</section></div>`}
function taskList(rows){return `<div class="attention-list">${rows.map(t=>`<div class="attention-row"><span class="attention-symbol">${icon('check')}</span><div><strong>${esc(t.title)}</strong><small>${esc(t.discipline)} · ${esc(t.assignee)} · ${fmtDate(t.due)}</small></div>${status(t.status)}</div>`).join('')||'<div class="empty-state">لا توجد مهام لهذا المشروع.</div>'}</div>`}
function fileList(rows){return `<div>${rows.map(f=>`<div class="file-row"><span class="file-type ${f.type==='PDF'?'pdf':f.type==='DWG'?'cad':f.type==='XLS'?'xls':''}">${esc(f.type)}</span><span class="file-info"><strong>${esc(f.name)}</strong><small>${esc(f.code)} · ${esc(f.discipline)} · ${esc(f.owner)}</small></span><span class="version">v${f.version}</span>${status(f.state)}</div>`).join('')}</div>`}
function changes(){const s=getState();content.innerHTML=`${renderHeading('إدارة المشروع / التغييرات','التغييرات الهندسية','راجع طلبات العميل، آثارها، والمهام التي تتطلب تنسيقًا.',button('new-change','تسجيل طلب تغيير','btn btn-primary','plus'))}<div class="grid grid-main-side"><div class="change-stack">${s.changes.map(c=>`<article class="panel panel-pad change-card" data-change-id="${esc(c.id)}"><div class="panel-head"><div><span class="tag gold">${esc(c.id)}</span> <span class="tag">${fmtDate(c.date)}</span><h2 style="margin-top:8px">${esc(c.title)}</h2><p>${esc(c.description)}</p></div>${status(c.status)}</div><div class="detail-row"><span>المشروع</span><b>${esc(projectName(c.project,s))}</b></div><div class="detail-row"><span>مقدم الطلب</span><b>${esc(c.requester)}</b></div><div class="detail-row"><span>التخصصات المتأثرة</span><div>${c.disciplines.map(d=>`<span class="tag">${esc(d)}</span>`).join(' ')}</div></div>${c.id==='CR-017'?`<div class="impact-grid" style="margin-top:12px"><div class="impact-cell high"><small>العمارة</small><strong>أثر مرتفع</strong></div><div class="impact-cell medium"><small>التكييف</small><strong>أثر مرتفع</strong></div><div class="impact-cell medium"><small>الكهرباء</small><strong>أثر متوسط</strong></div><div class="impact-cell medium"><small>الكميات</small><strong>أثر متوسط</strong></div><div class="impact-cell low"><small>الجدول</small><strong>أثر منخفض</strong></div><div class="impact-cell medium"><small>الإنشائي</small><strong>يتطلب مراجعة</strong></div></div>`:''}<hr class="section-divider"><div class="notice"><div><strong>تحليل تجريبي مرتبط بسجلات المشروع.</strong> يعرض أثرًا مبدئيًا ومصادره؛ يلزم اعتماد المهندس قبل التنفيذ.</div></div><div style="display:flex;gap:7px;flex-wrap:wrap;margin-top:12px"><button class="btn btn-primary btn-sm" data-action="analyze" data-id="${esc(c.id)}">تحليل الأثر</button><button class="btn btn-soft btn-sm" data-action="coordination" data-id="${esc(c.id)}">خطة التنسيق</button><button class="btn btn-sm" data-action="proposal" data-id="${esc(c.id)}">مقترح تصميم</button><a class="btn btn-sm" href="thread.html?change=${encodeURIComponent(c.id)}">ترابط العناصر</a></div><div class="source-row" style="margin-top:10px">المصادر: ${(c.sources||['سجل طلب التغيير']).map(x=>`<span class="source-chip">${esc(x)}</span>`).join('')}</div></article>`).join('')}</div><aside class="panel panel-pad"><div class="panel-head"><div><h2>تعارضات المزامنة</h2><p>تم اكتشافها من سجل الإصدارات</p></div><span class="status bad">١ مفتوح</span></div><div class="notice red"><div><strong>مرجع إصدار غير متزامن.</strong><br>M-203 v2 يشير إلى A-104 v2 بينما آخر إصدار هو A-104 v3.</div></div><a class="btn btn-soft" href="files.html" style="width:100%;margin-top:10px">فتح سجل الملفات</a><hr class="section-divider"><div class="panel-head"><div><h2>القرارات الهندسية</h2><p>القرارات المرتبطة بطلبات التغيير</p></div><button class="link" data-action="new-decision">+ قرار</button></div><div class="attention-list"><div class="attention-row"><span class="attention-symbol">D</span><div><strong>D-014 · موقع غرفة الاجتماعات</strong><small>مركز الرياض · ٢٨ سبتمبر</small></div>${status('معتمد')}</div><div class="attention-row"><span class="attention-symbol gold">D</span><div><strong>D-019 · اختيار نظام الواجهة</strong><small>مجمع النخيل · ٢٦ سبتمبر</small></div>${status('بانتظار الاعتماد')}</div></div></aside></div>`}
function thread(){content.innerHTML=`${renderHeading('مركز الرياض للأعمال / التنسيق','ترابط المشروع الهندسي','تابع كيف ينتقل أثر التغيير بين الطلب والقرار والملفات والمهام.',button('reset-thread','إعادة ضبط العرض','btn',''))}<div class="grid grid-main-side"><section class="panel panel-pad"><div class="panel-head"><div><h2>سلسلة أثر CR-017</h2><p>اضغط على أي عنصر لعرض مالكه ومصادره والعناصر التابعة</p></div><span class="demo-label">مصدر البيانات: سجل المشروع</span></div><div class="thread-map" id="threadMap"><div class="thread-col"><button class="thread-node selected" data-node="CR-017"><span class="node-kind">طلب عميل</span><strong><i class="node-dot">↗</i>CR-017</strong><small>توسيع غرفة الاجتماعات 03</small></button><button class="thread-node" data-node="R-012"><span class="node-kind">متطلب</span><strong><i class="node-dot">◎</i>R-012</strong><small>سعة الغرفة 24 شخصًا</small></button><button class="thread-node" data-node="D-014"><span class="node-kind">قرار هندسي</span><strong><i class="node-dot">✓</i>D-014</strong><small>موافقة مبدئية</small></button></div><div class="thread-col"><button class="thread-node" data-node="CHG-0042"><span class="node-kind">تغيير هندسي</span><strong><i class="node-dot">↻</i>CHG-0042</strong><small>قيد تنسيق التخصصات</small></button><button class="thread-node" data-node="ARCH-031"><span class="node-kind">مهمة</span><strong><i class="node-dot">☷</i>ARCH-031</strong><small>تحديث مخطط معماري</small></button></div><div class="thread-col"><button class="thread-node" data-node="A-104 v3"><span class="node-kind">ملف معماري</span><strong><i class="node-dot">▤</i>A-104 · v3</strong><small>آخر إصدار مسجل</small></button><button class="thread-node" data-node="M-203 v2"><span class="node-kind">مرجع ميكانيكي</span><strong><i class="node-dot">▤</i>M-203 · v2</strong><small>يشير إلى A-104 v2</small></button><button class="thread-node" data-node="APR-008"><span class="node-kind">اعتماد العميل</span><strong><i class="node-dot">✓</i>APR-008</strong><small>بانتظار رد العميل</small></button></div></div></section><aside class="panel thread-detail" id="threadDetail"><span class="page-kicker">طلب العميل · CR-017</span><h2>توسيع غرفة الاجتماعات 03</h2><p>زيادة المساحة المطلوبة ترتبط بمراجعة المخطط المعماري والتكييف والإنارة وجدول الكميات.</p><div class="detail-row"><span>المالك</span><b>سارة الحربي</b></div><div class="detail-row"><span>الحالة</span>${status('قيد التنسيق')}</div><div class="detail-row"><span>العناصر التابعة</span><b>٧ سجلات</b></div><hr class="section-divider"><b style="font-size:9px">المراجع المرتبطة</b><div style="margin-top:7px"><span class="source-chip">A-104 v3</span><span class="source-chip">M-203 v2</span><span class="source-chip">D-014</span></div><div class="notice warn" style="margin-top:13px">يظهر تعارض مرجعي بين M-203 v2 وA-104 v3. راجعي الملف قبل إغلاق التغيير.</div></aside></div>`}

function tasks(){const s=getState(), pid=new URLSearchParams(location.search).get('project');let rows=s.tasks.filter(t=>!pid||t.project===pid);content.innerHTML=`${renderHeading('تخطيط المكتب / توزيع العمل','المهام وعبء العمل','لوحة واحدة للأولويات والمواعيد والمسؤوليات عبر التخصصات.',button('new-task','إضافة مهمة','btn btn-primary','plus'))}<div class="filter-bar"><input class="search-input" id="taskFilter" placeholder="ابحث في المهام"><select class="select" id="taskProject"><option value="">كل المشاريع</option>${s.projects.map(p=>`<option value="${p.id}" ${pid===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select><span class="count-note">${rows.filter(t=>t.status!=='مكتملة').length} مهام مفتوحة</span></div><div class="task-board">${statuses.filter(x=>x!=='متأخرة').map(st=>{let group=rows.filter(t=>t.status===st);return `<section class="task-column"><div class="column-head"><strong>${st}</strong><span class="column-count">${group.length}</span></div>${group.map(t=>`<article class="task-card"><div class="task-top"><span class="tag ${t.priority==='عالية'?'red':t.priority==='متوسطة'?'gold':''}">${esc(t.priority)}</span><button class="link" data-action="task-done" data-id="${esc(t.id)}">⋯</button></div><h3>${esc(t.title)}</h3><p>${esc(projectName(t.project,s))}</p><div class="task-tags"><span class="tag">${esc(t.discipline)}</span>${t.change?`<span class="tag">${esc(t.change)}</span>`:''}</div><div class="task-foot"><small>${fmtDate(t.due)} · ${esc(t.assignee)}</small><span class="avatar">${esc(t.assignee[0])}</span></div></article>`).join('')||'<div class="empty-state">لا توجد مهام</div>'}</section>`}).join('')}<section class="task-column"><div class="column-head"><strong>متأخرة</strong><span class="column-count">${rows.filter(t=>t.status==='متأخرة').length}</span></div>${rows.filter(t=>t.status==='متأخرة').map(t=>`<article class="task-card"><div class="task-top"><span class="tag red">متأخرة</span></div><h3>${esc(t.title)}</h3><p>${esc(projectName(t.project,s))}</p><div class="task-foot"><small>${fmtDate(t.due)} · ${esc(t.assignee)}</small></div></article>`).join('')||'<div class="empty-state">لا توجد مهام متأخرة</div>'}</section></div>`}
function files(){const s=getState(),pid=new URLSearchParams(location.search).get('project'),rows=s.files;content.innerHTML=`${renderHeading('إدارة المستندات / سجل المكتب','الملفات والإصدارات','مرجع موحد للرسومات والمستندات مع حالة المراجعة والارتباطات.',button('upload','تسجيل ملف','btn btn-primary','plus'))}<div class="notice warn" style="margin-bottom:14px"><div><strong>تعارض إصدار يحتاج مراجعة:</strong> M-203 v2 يشير إلى A-104 v2، بينما أحدث إصدار معماري هو A-104 v3.</div><a class="link" href="thread.html">عرض الترابط ←</a></div><div class="filter-bar"><input class="search-input" id="fileFilter" placeholder="ابحث بالاسم أو رقم الملف"><select class="select" id="fileDiscipline"><option value="">كل التخصصات</option>${[...new Set(rows.map(f=>f.discipline))].map(d=>`<option>${esc(d)}</option>`).join('')}</select><span class="count-note">${rows.length} مستندات في سجل العرض</span></div><section class="panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>المستند</th><th>رقم المستند</th><th>التخصص</th><th>المالك</th><th>آخر تحديث</th><th>الإصدار</th><th>الحالة</th><th></th></tr></thead><tbody>${rows.map(f=>`<tr><td><div class="row-main"><span class="file-type ${f.type==='PDF'?'pdf':f.type==='DWG'?'cad':'xls'}">${esc(f.type)}</span><span><strong>${esc(f.name)}</strong><small>${(f.refs||[]).map(esc).join(' · ')||'لا توجد ارتباطات مسجلة'}</small></span></div></td><td><b>${esc(f.code)}</b></td><td>${esc(f.discipline)}</td><td>${esc(f.owner)}</td><td>${fmtDate(f.updated)}</td><td><span class="version">v${f.version}</span></td><td>${status(f.state)}</td><td><button class="btn btn-sm" data-action="file-detail" data-id="${esc(f.id)}">التفاصيل</button></td></tr>`).join('')}</tbody></table></div></section><div class="grid grid-halves"><section class="panel panel-pad"><div class="panel-head"><div><h2>قواعد ضبط الإصدار</h2><p>مراجعات قبل مشاركة حزمة التصميم</p></div></div><div class="attention-list"><div class="attention-row"><span class="attention-symbol red">!</span><div><strong>مرجع أقدم في M-203</strong><small>يلزم تحديث مرجع A-104 قبل إغلاق التنسيق</small></div>${status('تحتاج إجراء')}</div><div class="attention-row"><span class="attention-symbol">✓</span><div><strong>المخطط المعماري A-104</strong><small>آخر إصدار مسجل v3</small></div>${status('محدث')}</div></div></section><section class="panel panel-pad"><div class="panel-head"><div><h2>سجل الحزم</h2><p>تجهيزات التسليم المرتبطة بالمشروع</p></div></div><div class="detail-row"><span>حزمة التصميم الأولي</span><b>4 مستندات · قيد المراجعة</b></div><div class="detail-row"><span>حزمة تقرير سبتمبر</span><b>2 مستندات · جاهزة للمشاركة</b></div></section></div>`}
function approvals(){const s=getState(),rows=s.approvals;content.innerHTML=`${renderHeading('بوابة العميل / دورة المراجعة','الاعتمادات والقرارات','تابع ما أُرسل، وما ينتظر ردًا، والقرارات الهندسية المرتبطة.',button('new-decision','توثيق قرار','btn btn-primary','plus'))}<div class="stats-grid grid"><article class="panel stat-card"><div class="stat-label">بانتظار الرد</div><div class="stat-value">${rows.filter(a=>a.status==='بانتظار العميل').length}</div><div class="stat-foot">طلبات اعتماد مفتوحة</div></article><article class="panel stat-card"><div class="stat-label">معتمد</div><div class="stat-value">${rows.filter(a=>a.status==='معتمد').length}</div><div class="stat-foot">قرارات محفوظة في السجل</div></article><article class="panel stat-card"><div class="stat-label">متوسط زمن الرد</div><div class="stat-value">2.4</div><div class="stat-foot">يوم عمل · بيانات توضيحية</div></article><article class="panel stat-card"><div class="stat-label">القرارات الموثقة</div><div class="stat-value">12</div><div class="stat-foot">على مستوى المكتب · عرض تجريبي</div></article></div><div class="grid grid-main-side"><section class="panel panel-pad"><div class="panel-head"><div><h2>طلبات الاعتماد</h2><p>المستند أو القرار والجهة المسؤولة عن المراجعة</p></div><button class="btn btn-sm" data-action="export">تصدير القائمة</button></div><div class="attention-list">${rows.map(a=>`<article class="approval-card"><div class="approval-top"><span class="tag">${esc(a.id)}</span>${status(a.status)}</div><h3>${esc(a.title)}</h3><p>${esc(projectName(a.project,s))} · ${esc(a.recipient)}</p><div class="approval-meta"><span>أُرسل ${fmtDate(a.sent)}</span><span>${esc(a.type)}</span>${a.change?`<a class="link" href="changes.html">${esc(a.change)}</a>`:''}</div><div class="approval-actions"><button class="btn btn-sm" data-action="approval-detail" data-id="${esc(a.id)}">عرض التفاصيل</button>${a.status==='بانتظار العميل'?`<button class="btn btn-soft btn-sm" data-action="remind" data-id="${esc(a.id)}">تجهيز تذكير</button>`:''}</div></article>`).join('')}</div></section><aside class="panel panel-pad"><div class="panel-head"><div><h2>سجل القرارات</h2><p>قرارات مؤثرة في التصميم والتنفيذ</p></div></div><div class="attention-list"><div class="attention-row"><span class="attention-symbol">D</span><div><strong>D-014 · موقع غرفة الاجتماعات</strong><small>مركز الرياض · ٢٨ سبتمبر</small></div>${status('معتمد')}</div><div class="attention-row"><span class="attention-symbol gold">D</span><div><strong>D-019 · اختيار نظام الواجهة</strong><small>مجمع النخيل · ٢٦ سبتمبر</small></div>${status('بانتظار الاعتماد')}</div></div><div class="notice" style="margin-top:12px">تسجيل القرار يحفظ صاحبه وتاريخه ومراجع المستندات في سجل العرض.</div></aside></div>`}
function team(){const s=getState();content.innerHTML=`${renderHeading('إدارة المكتب / الموارد','الفريق وعبء العمل','توزيع واضح حسب التخصص والقدرة الحالية والمشاريع المسندة.',button('invite','إضافة عضو','btn btn-primary','plus'))}<div class="stats-grid grid"><article class="panel stat-card"><div class="stat-label">أعضاء الفريق</div><div class="stat-value">${s.team.length}</div><div class="stat-foot">تخصصات هندسية وإدارية</div></article><article class="panel stat-card"><div class="stat-label">متوسط الإشغال</div><div class="stat-value">${Math.round(s.team.reduce((n,t)=>n+t.capacity,0)/s.team.length)}٪</div><div class="stat-foot">من السعة الأسبوعية المسجلة</div></article><article class="panel stat-card"><div class="stat-label">سعة متاحة</div><div class="stat-value">${s.team.filter(t=>t.capacity<60).length}</div><div class="stat-foot">أعضاء دون إشغال ٦٠٪</div></article><article class="panel stat-card"><div class="stat-label">التخصصات</div><div class="stat-value">5</div><div class="stat-foot">معماري · إنشائي · MEP · كميات</div></article></div><section class="panel panel-pad"><div class="panel-head"><div><h2>سجل أعضاء المكتب</h2><p>تُظهر النسب تقدير الإشغال الأسبوعي في بيانات العرض</p></div><span class="demo-label">بيانات توضيحية</span></div><div class="team-grid">${s.team.map(t=>`<article class="team-card"><div class="team-person"><span class="avatar ${esc(t.color)}">${esc(t.initial)}</span><div><strong>${esc(t.name)}</strong><small>${esc(t.role)}</small></div><button class="link" data-action="view-member">⋯</button></div><div class="detail-row"><span>التخصص</span><b>${esc(t.discipline)}</b></div><div class="detail-row"><span>مشاريع مسندة</span><b>${t.projects}</b></div><div class="capacity-label"><span>الإشغال الأسبوعي</span><b>${t.capacity}%</b></div><div class="progress ${t.capacity>80?'gold':''}"><span style="width:${t.capacity}%"></span></div><button class="btn btn-sm btn-soft" data-action="reassign" style="width:100%;margin-top:12px">مراجعة التوزيع</button></article>`).join('')}</div></section><section class="panel panel-pad" style="margin-top:14px"><div class="panel-head"><div><h2>توازن المهام حسب التخصص</h2><p>مهام مفتوحة من بيانات مساحة العرض</p></div></div>${[...new Set(s.tasks.filter(t=>t.status!=='مكتملة').map(t=>t.discipline))].map(d=>{let n=s.tasks.filter(t=>t.discipline===d&&t.status!=='مكتملة').length;return `<div class="detail-row"><span>${esc(d)}</span><b>${n} مهام</b><span class="progress"><span style="width:${Math.min(n*18,100)}%"></span></span></div>`}).join('')}</section>`}
function client(){const s=getState();content.innerHTML=`${renderHeading('تجربة مشاركة العميل / عرض المكتب','بوابة العميل','مساحة مبسطة لمراجعة المستندات والطلبات والقرارات دون كشف تفاصيل التشغيل الداخلي.','<span class="demo-label">معاينة فقط · لا يوجد دخول حقيقي</span>')}<section class="client-welcome"><span class="client-mark">أ</span><div><small>مرحبًا بشركة أفق للتطوير</small><h2>مركز الرياض للأعمال</h2><p>ملخص التقدم والمواد التي تحتاج مراجعتكم.</p></div><div class="client-progress"><b>68%</b><span>إنجاز المشروع</span><div class="progress"><span style="width:68%"></span></div></div></section><div class="stats-grid grid" style="margin-top:14px"><article class="panel stat-card"><div class="stat-label">طلبات بانتظاركم</div><div class="stat-value">${s.approvals.filter(a=>a.status==='بانتظار العميل').length}</div><div class="stat-foot">يمكن عرض التفاصيل في هذه المعاينة</div></article><article class="panel stat-card"><div class="stat-label">التسليم القادم</div><div class="stat-value" style="font-size:18px">${fmtDate('2026-10-07')}</div><div class="stat-foot">حزمة التصميم الأولي</div></article><article class="panel stat-card"><div class="stat-label">آخر تحديث</div><div class="stat-value" style="font-size:16px">${fmtDate('2026-10-01')}</div><div class="stat-foot">المخطط المعماري A-104 v3</div></article><article class="panel stat-card"><div class="stat-label">تحديثات جديدة</div><div class="stat-value">3</div><div class="stat-foot">منذ آخر مراجعة · توضيحي</div></article></div><div class="grid grid-two"><section class="panel panel-pad"><div class="panel-head"><div><h2>مواد بانتظار المراجعة</h2><p>اضغط على التفاصيل لعرض بطاقة المراجعة</p></div></div><div class="attention-list">${s.approvals.filter(a=>a.status==='بانتظار العميل').map(a=>`<div class="approval-card"><div class="approval-top"><span class="tag">${esc(a.id)}</span>${status(a.status)}</div><h3>${esc(a.title)}</h3><p>${esc(projectName(a.project,s))} · أُرسل ${fmtDate(a.sent)}</p><button class="btn btn-soft btn-sm" data-action="approval-detail" data-id="${esc(a.id)}">مراجعة المادة</button></div>`).join('')}</div></section><section class="panel panel-pad"><div class="panel-head"><div><h2>آخر المستجدات</h2><p>تحديثات مختارة للعميل</p></div></div>${activityList(s.activity.slice(0,3))}<div class="notice" style="margin-top:10px">روابط الاعتماد والإرسال الفعلي غير مفعلة في نموذج المعاينة.</div></section></div>`}
function ai(){const s=getState();content.innerHTML=`${renderHeading('تحليل مدعوم بسجل المشروع','مركز الذكاء الهندسي','افهم أثر التغيير وابحث في سياق المشروع. كل إجابة تجريبية تعرض مصادرها وحدودها.', '<span class="demo-label">محاكاة محلية · غير متصل بمزود AI</span>')}<div class="grid grid-two"><section class="panel panel-pad ai-panel"><div class="panel-head"><div><h2>اسألي عن المشروع</h2><p>تجيب المحاكاة من سجلات العرض المثبتة فقط</p></div><button class="btn btn-sm" data-action="clear-chat">محادثة جديدة</button></div><div class="chat-messages" id="chatMessages"><div class="msg ai">مرحبًا، أستطيع مساعدتك في العثور على معلومات مسجلة عن CR-017 أو الإصدارات أو المهام والاعتمادات.<small>المصدر: بيانات مساحة العرض</small></div></div><div class="suggestions"><button class="suggestion" data-question="ما أثر CR-017؟">ما أثر CR-017؟</button><button class="suggestion" data-question="هل يوجد تعارض في الإصدارات؟">هل يوجد تعارض في الإصدارات؟</button><button class="suggestion" data-question="ما الاعتمادات المنتظرة؟">ما الاعتمادات المنتظرة؟</button></div><form id="chatForm" class="chat-form"><input id="chatInput" placeholder="اكتبي سؤالًا عن بيانات المشروع…" required><button class="btn btn-primary" type="submit">إرسال ${icon('arrow')}</button></form></section><aside class="panel panel-pad"><div class="panel-head"><div><h2>تحليل أثر التغيير</h2><p>مراجعة أولية مع المراجع والبيانات الناقصة</p></div></div><div class="impact-summary"><span class="impact-badge">CR-017</span><h3>توسيع غرفة الاجتماعات 03</h3><p>مستوى الأثر المتوقع: متوسط إلى مرتفع</p></div><div class="impact-grid"><div class="impact-cell high"><small>العمارة</small><strong>مرتفع</strong></div><div class="impact-cell high"><small>التكييف</small><strong>مرتفع</strong></div><div class="impact-cell medium"><small>الكهرباء</small><strong>متوسط</strong></div><div class="impact-cell medium"><small>الكميات</small><strong>متوسط</strong></div><div class="impact-cell low"><small>الجدول</small><strong>منخفض</strong></div><div class="impact-cell medium"><small>الإنشائي</small><strong>غير محسوم</strong></div></div><div class="notice warn" style="margin-top:12px">معلومات ناقصة: الأبعاد النهائية ومراجعة الإنشائي. لا يعتمد هذا التحليل للتنفيذ.</div><div class="source-row" style="margin-top:10px">المصادر: ${['CR-017','A-104 v3','M-203 v2','D-014'].map(x=>`<span class="source-chip">${x}</span>`).join('')}</div><button class="btn btn-primary" data-action="analyze" style="width:100%;margin-top:12px">مراجعة تحليل الأثر ${icon('spark')}</button></aside></div><section class="panel panel-pad" style="margin-top:14px"><div class="panel-head"><div><h2>حدود المساعد الحالي</h2><p>شفافية قبل ربط الخدمة الحقيقية</p></div></div><div class="grid grid-three"><div class="notice">لا يوجد اتصال بمزود ذكاء اصطناعي حاليًا.</div><div class="notice">الإجابات التوضيحية لا تستبدل المراجعة الهندسية.</div><div class="notice">الربط القادم يحتاج API آمنًا وصلاحيات وسجل تدقيق.</div></div></section>`}
function reports(){const s=getState(),avg=Math.round(s.projects.reduce((n,p)=>n+p.progress,0)/s.projects.length);content.innerHTML=`${renderHeading('متابعة الأداء / المكتب','التقارير ومؤشرات الأداء','أرقام مجمعة لتسهيل قراءة تقدم المشاريع والمواعيد والتنسيق.',button('report','إنشاء ملخص','btn btn-primary','file'))}<div class="stats-grid grid"><article class="panel stat-card"><div class="stat-label">متوسط إنجاز المحفظة</div><div class="stat-value">${avg}%</div><div class="progress"><span style="width:${avg}%"></span></div></article><article class="panel stat-card"><div class="stat-label">المهام المتأخرة</div><div class="stat-value">${s.tasks.filter(t=>t.status==='متأخرة').length}</div><div class="stat-foot">تحتاج إلى مراجعة المسؤول والموعد</div></article><article class="panel stat-card"><div class="stat-label">طلبات التغيير المفتوحة</div><div class="stat-value">${s.changes.filter(c=>!['مكتمل','مغلق'].includes(c.status)).length}</div><div class="stat-foot">قيد التنسيق أو المراجعة</div></article><article class="panel stat-card"><div class="stat-label">الاعتمادات المنتظرة</div><div class="stat-value">${s.approvals.filter(a=>a.status==='بانتظار العميل').length}</div><div class="stat-foot">عبر ${new Set(s.approvals.filter(a=>a.status==='بانتظار العميل').map(a=>a.project)).size} مشاريع</div></article></div><div class="grid grid-two"><section class="panel panel-pad"><div class="panel-head"><div><h2>حالة المشاريع</h2><p>مقارنة الإنجاز بالخطة والمواعيد</p></div><span class="demo-label">تقرير عرض تجريبي</span></div>${s.projects.map(p=>`<div class="report-project"><div><strong>${esc(p.name)}</strong><small>${esc(p.code)} · ${esc(p.manager)}</small></div><span>${p.progress}%</span><div class="progress"><span style="width:${p.progress}%"></span></div>${status(p.status)}</div>`).join('')}</section><section class="panel panel-pad"><div class="panel-head"><div><h2>مؤشرات التنسيق</h2><p>قراءة من سجل المهام والإصدارات</p></div></div><div class="metric-row"><div><span>اكتمال المهام</span><b>${Math.round(s.tasks.filter(t=>t.status==='مكتملة').length/s.tasks.length*100)}%</b></div><div class="progress"><span style="width:${Math.round(s.tasks.filter(t=>t.status==='مكتملة').length/s.tasks.length*100)}%"></span></div></div><div class="metric-row"><div><span>المشاريع على المسار</span><b>${s.projects.filter(p=>p.status==='على المسار').length}/${s.projects.length}</b></div><div class="progress"><span style="width:${s.projects.filter(p=>p.status==='على المسار').length/s.projects.length*100}%"></span></div></div><div class="metric-row"><div><span>تعارضات إصدار مفتوحة</span><b>1</b></div><a class="link" href="files.html">مراجعة</a></div><div class="notice" style="margin-top:12px">المؤشرات مستمدة من بيانات العرض، وليست تقريرًا رسميًا للاستخدام التعاقدي.</div></section></div><section class="panel panel-pad" style="margin-top:14px"><div class="panel-head"><div><h2>سجل نشاط المكتب</h2><p>آخر التحديثات المسجلة في مساحة العرض</p></div></div>${activityList(s.activity)}</section>`}
function settings(){const s=getState();content.innerHTML=`${renderHeading('إدارة المكتب / التهيئة','إعدادات المكتب','إعدادات العرض ومساحة العمل. خيارات الحفظ موضعية على هذا المتصفح.',button('reset-demo','استعادة بيانات العرض','btn'))}<div class="grid grid-two"><section class="panel panel-pad"><div class="panel-head"><div><h2>بيانات مساحة العمل</h2><p>تعريف المكتب والمشروع الافتراضي</p></div></div><form id="settingsForm" class="form-grid"><div class="field full"><label>اسم المكتب</label><input name="office" value="${esc(s.settings.office)}" required></div><div class="field full"><label>المشروع الافتراضي</label><select name="project">${s.projects.map(p=>`<option value="${p.id}" ${s.settings.project===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div><div class="field"><label>العملة</label><select name="currency"><option value="SAR" ${s.settings.currency==='SAR'?'selected':''}>ريال سعودي (SAR)</option></select></div><div class="field"><label>اللغة</label><select name="language"><option value="ar">العربية</option></select></div><div class="field full"><button class="btn btn-primary" type="submit">حفظ التفضيلات</button></div></form></section><section class="panel panel-pad"><div class="panel-head"><div><h2>الصلاحيات والربط</h2><p>خيارات غير مفعلة في نسخة المعاينة</p></div></div><div class="attention-list"><div class="attention-row"><span class="attention-symbol">⌑</span><div><strong>تسجيل الدخول والصلاحيات</strong><small>يلزم خادم هوية قبل دعوة مستخدمين حقيقيين</small></div><span class="tag gold">لاحقًا</span></div><div class="attention-row"><span class="attention-symbol">✳</span><div><strong>ربط الذكاء الاصطناعي</strong><small>بعد مراجعة الواجهات، من خلال خدمة خادمية آمنة</small></div><span class="tag gold">لاحقًا</span></div><div class="attention-row"><span class="attention-symbol">▤</span><div><strong>تخزين الملفات</strong><small>الرفع الفعلي يتطلب تخزينًا وصلاحيات خلفية</small></div><span class="tag gold">لاحقًا</span></div></div></section></div><section class="panel panel-pad" style="margin-top:14px"><div class="panel-head"><div><h2>بيانات الجهاز</h2><p>البيانات التجريبية محفوظة محليًا في المتصفح الحالي</p></div><button class="btn btn-danger btn-sm" data-action="reset-demo">مسح البيانات المحلية</button></div><div class="notice">لا تضعي معلومات مشاريع أو مستندات سرية في هذه المعاينة العامة.</div></section>`}

const views={overview,projects,workspace,changes,thread,tasks,files,approvals,team,client,ai,reports,settings};
function render(){(views[page]||overview)();document.title=`${({overview:'نظرة عامة',projects:'المشاريع',workspace:'مساحة المشروع',changes:'التغييرات',thread:'ترابط المشروع',tasks:'المهام',files:'الملفات',approvals:'الاعتمادات',team:'الفريق',client:'بوابة العميل',ai:'مركز الذكاء',reports:'التقارير',settings:'إعدادات المكتب'})[page]||'نواة'} | نَواة`}
function openModal(title,body,submit='حفظ'){let root=$('#modalBackdrop');if(!root){root=document.createElement('div');root.id='modalBackdrop';root.className='modal-backdrop';root.innerHTML='<section class="modal" role="dialog" aria-modal="true"><header class="modal-head"><h2 id="modalTitle"></h2><button class="modal-close" data-action="close-modal" aria-label="إغلاق">×</button></header><form id="modalForm"><div class="modal-body" id="modalBody"></div><footer class="modal-foot"><button class="btn btn-primary" type="submit" id="modalSubmit"></button><button class="btn" type="button" data-action="close-modal">إلغاء</button></footer></form></section>';document.body.append(root)}$('#modalTitle',root).textContent=title;$('#modalBody',root).innerHTML=body;$('#modalSubmit',root).textContent=submit;root.classList.add('open')}
function modalFor(action,id=''){const s=getState(),projectOptions=s.projects.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('');const forms={
'new-project':['إضافة مشروع',`<div class="form-grid"><div class="field full"><label>اسم المشروع</label><input name="name" required placeholder="اسم واضح للمشروع"></div><div class="field"><label>العميل</label><input name="client" required></div><div class="field"><label>المدينة</label><input name="location" value="الرياض"></div><div class="field"><label>الموعد المستهدف</label><input type="date" name="due" required></div><div class="field"><label>نوع المشروع</label><select name="type"><option>مبنى تجاري</option><option>سكني</option><option>مكتبي</option><option>بنية تحتية</option></select></div></div>`],
'new-task':['إضافة مهمة',`<div class="form-grid"><div class="field full"><label>وصف المهمة</label><input name="title" required></div><div class="field"><label>المشروع</label><select name="project">${projectOptions}</select></div><div class="field"><label>التخصص</label><select name="discipline"><option>معماري</option><option>إنشائي</option><option>ميكانيكي</option><option>كهربائي</option><option>كميات</option><option>إدارة المشروع</option></select></div><div class="field"><label>المسؤول</label><select name="assignee">${s.team.map(t=>`<option>${esc(t.name)}</option>`).join('')}</select></div><div class="field"><label>الموعد</label><input name="due" type="date" required></div><div class="field"><label>الأولوية</label><select name="priority"><option>متوسطة</option><option>عالية</option><option>عادية</option></select></div></div>`],
'new-change':['تسجيل طلب تغيير',`<div class="form-grid"><div class="field full"><label>عنوان الطلب</label><input name="title" required></div><div class="field"><label>المشروع</label><select name="project">${projectOptions}</select></div><div class="field"><label>مقدم الطلب</label><input name="requester" required></div><div class="field full"><label>وصف التغيير</label><textarea name="description" required></textarea></div><div class="field"><label>التخصصات المتأثرة</label><input name="disciplines" placeholder="معماري، كهربائي"></div><div class="field"><label>الأولوية</label><select name="priority"><option>متوسطة</option><option>عالية</option><option>عادية</option></select></div></div>`],
'new-decision':['توثيق قرار هندسي',`<div class="form-grid"><div class="field"><label>رقم القرار</label><input name="id" placeholder="D-020"></div><div class="field"><label>المشروع</label><select name="project">${projectOptions}</select></div><div class="field full"><label>موضوع القرار</label><input name="title" required></div><div class="field full"><label>المبررات والمراجع</label><textarea name="description" required></textarea></div></div>`],
'upload':['تسجيل مستند في السجل',`<div class="form-grid"><div class="field full"><label>اسم المستند</label><input name="name" required></div><div class="field"><label>رقم المستند</label><input name="code" required placeholder="A-105"></div><div class="field"><label>نوع الملف</label><select name="type"><option>PDF</option><option>DWG</option><option>XLS</option></select></div><div class="field"><label>التخصص</label><select name="discipline"><option>معماري</option><option>إنشائي</option><option>ميكانيكي</option><option>كهربائي</option><option>كميات</option></select></div><div class="field"><label>المالك</label><select name="owner">${s.team.map(t=>`<option>${esc(t.name)}</option>`).join('')}</select></div><div class="field full"><div class="notice warn">تُحفظ بيانات وصفية داخل العرض فقط. رفع الملف وتخزينه غير مفعّلين.</div></div></div>`],
'invite':['إضافة عضو للفريق',`<div class="form-grid"><div class="field"><label>الاسم</label><input name="name" required></div><div class="field"><label>الدور</label><select name="role"><option>مهندس</option><option>مدير مشروع</option><option>عميل</option></select></div><div class="field full"><label>التخصص</label><input name="discipline" required></div><div class="field full"><div class="notice">لن تُرسل دعوة فعلية؛ هذه إضافة محلية لبيانات المعاينة.</div></div></div>`],
'analyze':['تحليل أثر تجريبي · CR-017',`<div class="notice warn"><div><strong>نتيجة محاكاة محلية وليست ذكاءً اصطناعيًا متصلًا.</strong><br>قد يؤثر توسيع الغرفة على المخطط المعماري والتكييف والإنارة والكميات. الأثر الإنشائي غير محسوم ويتطلب مراجعة مهندس.</div></div><h3>المصادر المستخدمة</h3><span class="source-chip">CR-017</span><span class="source-chip">A-104 v3</span><span class="source-chip">M-203 v2</span><span class="source-chip">D-014</span><h3>معلومات مطلوبة</h3><p>الأبعاد النهائية ومراجعة المهندس الإنشائي. لم تُنشأ مهام أو اعتمادات.</p>`],
'approval-detail':['تفاصيل الاعتماد',(()=>{const a=s.approvals.find(x=>x.id===id);return a?`<div class="approval-card"><span class="tag">${esc(a.id)}</span>${status(a.status)}<h3>${esc(a.title)}</h3><p>${esc(projectName(a.project,s))} · ${esc(a.recipient)}</p><div class="detail-row"><span>تاريخ الإرسال</span><b>${fmtDate(a.sent)}</b></div><div class="detail-row"><span>النوع</span><b>${esc(a.type)}</b></div><div class="notice warn">معاينة فقط: لا يوجد إرسال أو اعتماد خارجي مفعّل.</div></div>`:'<p>لم يتم العثور على الاعتماد.</p>'})()],
'report':['ملخص أداء المكتب',`<div class="notice"><div><strong>موجز المكتب · ${fmtDate('2026-10-01')}</strong><br>المشاريع: ${s.projects.length} · المهام: ${s.tasks.length} · التغييرات المفتوحة: ${s.changes.length} · الاعتمادات المنتظرة: ${s.approvals.filter(a=>a.status==='بانتظار العميل').length}.</div></div><p>هذا ملخص توضيحي من بيانات العرض التجريبية.</p>`]};const item=forms[action];if(item){openModal(item[0],item[1],['analyze','approval-detail','report'].includes(action)?'إغلاق':'حفظ');$('#modalForm').dataset.action=action}}
function handleModalSubmit(form){const key=form.dataset.action,data=new FormData(form),v=n=>String(data.get(n)||'').trim();updateState(s=>{if(key==='new-project'){s.projects.unshift({id:makeId('P'),code:`NAWA-${String(s.projects.length+1).padStart(3,'0')}`,name:v('name'),client:v('client'),manager:s.user?.name||'جوري العروي',location:v('location')||'الرياض',type:v('type'),start:new Date().toISOString().slice(0,10),due:v('due'),progress:0,status:'على المسار',team:1,budget:0});s.activity.unshift({text:'أُضيف مشروع جديد',detail:v('name'),time:'الآن'})}if(key==='new-task')s.tasks.unshift({id:makeId('T'),title:v('title'),project:v('project'),discipline:v('discipline'),assignee:v('assignee'),priority:v('priority'),due:v('due'),status:'قائمة المهام',change:''});if(key==='new-change')s.changes.unshift({id:makeId('CR'),title:v('title'),project:v('project'),requester:v('requester'),date:new Date().toISOString().slice(0,10),status:'جديد',priority:v('priority'),description:v('description'),disciplines:v('disciplines').split(/[،,]/).map(x=>x.trim()).filter(Boolean),sources:[]});if(key==='new-decision')s.activity.unshift({text:`تم توثيق القرار ${v('id')||makeId('D')}`,detail:v('title'),time:'الآن'});if(key==='upload')s.files.unshift({id:makeId('F'),name:v('name'),code:v('code'),discipline:v('discipline'),type:v('type'),version:1,updated:new Date().toISOString().slice(0,10),owner:v('owner'),state:'مسودة',refs:[]});if(key==='invite')s.team.unshift({name:v('name'),initial:v('name')[0]||'م',discipline:v('discipline'),role:v('role'),capacity:0,color:'',projects:0});});$('#modalBackdrop')?.classList.remove('open');render();toast('تم الحفظ في بيانات العرض المحلية')}

render();
document.addEventListener('click',e=>{const action=e.target.closest('[data-action]');if(action){const a=action.dataset.action,id=action.dataset.id;if(['new-project','new-task','new-change','new-decision','upload','invite','analyze','approval-detail','report'].includes(a)){modalFor(a,id);return}if(a==='close-modal'){$('#modalBackdrop')?.classList.remove('open');return}if(a==='reset-demo'){if(confirm('استعادة بيانات العرض التجريبية؟'))resetState();return}if(a==='task-done'){updateState(s=>{const t=s.tasks.find(x=>x.id===id);if(t)t.status='مكتملة'});render();toast('أُغلقت المهمة في العرض');return}if(a==='clear-chat'){$('#chatMessages').innerHTML='<div class="msg ai">بدأت محادثة جديدة. اسأليني عن بيانات المشروع التجريبية.<small>المصدر: بيانات مساحة العرض</small></div>';return}if(a==='remind'){toast('تم تجهيز تذكير للمعاينة فقط؛ لم يُرسل للعميل');return}if(a==='notifications'){const unseen=getState().notifications.filter(n=>!n.seen);toast(unseen.map(n=>n.text).join(' · ')||'لا توجد إشعارات جديدة');updateState(s=>s.notifications.forEach(n=>n.seen=true));return}if(a==='menu'){document.body.classList.toggle('menu-open');return}if(a==='close-menu'){document.body.classList.remove('menu-open');return}if(a==='office-switch'){toast('مساحة المكتب الحالية: '+getState().settings.office);return}if(a==='file-detail'){const f=getState().files.find(x=>x.id===id);if(f){openModal(f.name,`<span class="tag">${esc(f.code)}</span><div class="detail-row"><span>الإصدار</span><b>v${f.version}</b></div><div class="detail-row"><span>التخصص والمالك</span><b>${esc(f.discipline)} · ${esc(f.owner)}</b></div><div class="detail-row"><span>الحالة</span>${status(f.state)}</div><div class="notice">${(f.refs||[]).length?'المراجع المرتبطة: '+f.refs.map(esc).join('، '):'لا توجد روابط مسجلة.'}</div>`,'إغلاق')}return}if(a==='export'){toast('تصدير القوائم غير مفعّل في نموذج المعاينة');return}if(a==='view-member'||a==='reassign'){toast('هذه الميزة قيد التجهيز في نموذج العرض');return}}
const node=e.target.closest('.thread-node');if(node){const labels={'CR-017':['طلب العميل · CR-017','توسيع غرفة الاجتماعات 03','زيادة المساحة ترتبط بمراجعة المخطط المعماري والتكييف والإنارة والكميات.'],'R-012':['متطلب · R-012','سعة الغرفة 24 شخصًا','متطلب موثق في سجل المشروع ويرتبط بطلب التغيير.'],'D-014':['قرار هندسي · D-014','موافقة مبدئية','يلزم استكمال مراجعة التخصصات قبل إغلاق التغيير.'],'CHG-0042':['تغيير هندسي','قيد تنسيق التخصصات','يشمل التغيير تحديث المخططات والمراجع التابعة.'],'ARCH-031':['مهمة','تحديث المخطط المعماري','المسؤول: سارة الحربي · مرتبطة بالتغيير CR-017.'],'A-104 v3':['ملف معماري','A-104 · v3','آخر إصدار معماري مسجل في مساحة العرض.'],'M-203 v2':['مرجع ميكانيكي','M-203 · v2','يشير إلى إصدار معماري أقدم ويحتاج مزامنة.'],'APR-008':['اعتماد العميل','APR-008','بانتظار رد العميل على المخطط المعماري A-104 v3.']},d=labels[node.dataset.node]||labels['CR-017'];$$('.thread-node').forEach(n=>n.classList.toggle('selected',n===node));$('#threadDetail').innerHTML=`<span class="page-kicker">${esc(d[0])}</span><h2>${esc(d[1])}</h2><p>${esc(d[2])}</p><div class="detail-row"><span>المشروع</span><b>مركز الرياض للأعمال</b></div><div class="detail-row"><span>الحالة</span>${status(node.dataset.node==='M-203 v2'?'مرجع قديم':'قيد المتابعة')}</div><hr class="section-divider"><b style="font-size:9px">المراجع المرتبطة</b><div><span class="source-chip">CR-017</span><span class="source-chip">A-104 v3</span><span class="source-chip">M-203 v2</span></div><div class="notice warn" style="margin-top:12px">راجع سجل المصدر قبل اتخاذ قرار هندسي.</div>`;return}
const suggestion=e.target.closest('.suggestion');if(suggestion){$('#chatInput').value=suggestion.dataset.question||suggestion.textContent;$('#chatInput').focus()}});
document.addEventListener('submit',e=>{if(e.target.id==='modalForm'){e.preventDefault();if(['analyze','approval-detail','report'].includes(e.target.dataset.action)){$('#modalBackdrop').classList.remove('open');return}handleModalSubmit(e.target);return}if(e.target.id==='settingsForm'){e.preventDefault();const d=new FormData(e.target);updateState(s=>{s.settings.office=d.get('office');s.settings.project=d.get('project');s.settings.currency=d.get('currency')});toast('حُفظت إعدادات مساحة العمل');render();return}if(e.target.id==='chatForm'){e.preventDefault();const input=$('#chatInput'),q=input.value.trim();if(!q)return;const box=$('#chatMessages');box.insertAdjacentHTML('beforeend',`<div class="msg user">${esc(q)}</div>`);input.value='';let ans='لا أجد سجلًا كافيًا للإجابة. اسألي عن CR-017 أو A-104 أو الاعتمادات.';let src='بيانات مساحة العرض';if(/تعارض|إصدار|تكييف/.test(q)){ans='يوجد تعارض مرجعي واحد: M-203 v2 يشير إلى A-104 v2، بينما أحدث إصدار معماري مسجل هو A-104 v3. يلزم تنسيق الفريق قبل الإغلاق.';src='M-203 v2 · A-104 v3'}else if(/اعتماد|عميل/.test(q)){ans='يوجد طلبان بانتظار العميل: مخطط A-104 v3 لمركز الرياض، وتقرير تقدم سبتمبر لفيلا الروضة.';src='APR-008 · APR-009'}else if(/cr-017|أثر|غرفة/.test(q)){ans='CR-017 يطلب توسيع غرفة الاجتماعات 03 بنسبة 20٪. قد يتأثر المخطط والتكييف والإنارة والكميات، أما الأثر الإنشائي فيحتاج مراجعة.';src='CR-017 · A-104 v3 · M-203 v2'}else if(/مهمة|تأخير/.test(q)){ans=`هناك ${getState().tasks.filter(t=>t.status==='متأخرة').length} مهام متأخرة في بيانات العرض. راجعي لوحة المهام للمسؤولين والمواعيد.`;src='سجل المهام'}setTimeout(()=>{box.insertAdjacentHTML('beforeend',`<div class="msg ai">${esc(ans)}<small>إجابة محاكاة · المصادر: ${esc(src)}</small></div>`);box.scrollTop=box.scrollHeight},180);box.scrollTop=box.scrollHeight}});
$('#roleSelect')?.addEventListener('change',e=>{updateState(s=>{s.user={...(s.user||{name:'جوري العروي',initial:'ج'}),role:e.target.value}});render();toast('معاينة الدور: '+e.target.selectedOptions[0].textContent)});
$('#globalSearch')?.addEventListener('input',e=>{const q=e.target.value.trim().toLowerCase(),box=$('#searchResults');if(!q){box.innerHTML='';box.classList.remove('open');return}const s=getState(),matches=[...s.projects.map(p=>({label:p.name,detail:p.code,url:`workspace.html?project=${p.id}`})),...s.files.map(f=>({label:f.name,detail:f.code,url:'files.html'})),...s.changes.map(c=>({label:c.title,detail:c.id,url:'changes.html'}))].filter(x=>(x.label+' '+x.detail).toLowerCase().includes(q)).slice(0,6);box.innerHTML=matches.map(x=>`<a href="${x.url}"><strong>${esc(x.label)}</strong><small>${esc(x.detail)}</small></a>`).join('')||'<div class="empty-state">لا توجد نتائج مطابقة</div>';box.classList.add('open')});
$('#projectFilter')?.addEventListener('input',e=>$$('.data-table tbody tr').forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(e.target.value.toLowerCase())));
$('#projectStatus')?.addEventListener('change',e=>$$('.data-table tbody tr').forEach(r=>r.hidden=!!e.target.value&&!r.textContent.includes(e.target.value)));
$('#taskFilter')?.addEventListener('input',e=>$$('.task-card').forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(e.target.value.toLowerCase())));
$('#taskProject')?.addEventListener('change',e=>location.href=e.target.value?`tasks.html?project=${e.target.value}`:'tasks.html');
$('#fileFilter')?.addEventListener('input',e=>$$('.data-table tbody tr').forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(e.target.value.toLowerCase())));
$('#fileDiscipline')?.addEventListener('change',e=>$$('.data-table tbody tr').forEach(r=>r.hidden=!!e.target.value&&!r.textContent.includes(e.target.value)));
document.addEventListener('click',e=>{if(e.target.id==='modalBackdrop')e.target.classList.remove('open')});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#modalBackdrop')?.classList.remove('open');document.body.classList.remove('menu-open')}});
